    def test_manual_steps_relabelled_with_fixed_reasons(self) -> None:
        decisions = resolve_side(self.left, self.right, self.seqs, "left")
        result = decoded(resolve_merge(self.plan, self.left, self.right, decisions))
        self.assertEqual(
