        self.assertEqual(len(result["steps"]), 1)
        step = result["steps"][0]
        self.assertEqual(step["entry"]["auth"], {"keyVersion": 1, "node": "node-a"})
        self.assertEqual(step["action"], "accept")
        self.assertEqual(step["reason"], "extension")


