class ProofPlanResolutionTest(CommitCase):
    def test_invalid_proofs_raise_invalid_proof_error(self) -> None:
        with self.assertRaises(InvalidProofError):
            self.commit(left=b"garbage\n")
        with self.assertRaises(InvalidProofError):
